attribute vec2 aChan;    // W11: visible channel centre / half width (units, see channel05)
varying vec2 vChan;
#endif
uniform float uTime;
uniform vec4 uHide;      // s03Start, s04Start, chuteMark, unused
varying vec2 vUV;
varying float vHalfW;
varying float vSpeed;
varying float vSkirt;
varying float vHide;
varying vec4 vStyle;
varying float vCore;
