      // replay the cinematic deterministically up to the checkpoint time
      const steps = Math.round((cp.t ?? 0) / (1 / 30));
      settle(steps, 1 / 30);
    } else {
      startRide();
      hud.showHint(null);
      const sTarget = cp.s ?? course.stage('11').s0;
      st.s = sTarget;
